// useTelegram.ts
import { useEffect } from 'react';

export function getWebApp() {
  return typeof window !== 'undefined' ? window.Telegram?.WebApp : undefined;
}

export function isTelegramWebApp(): boolean {
  return getWebApp() !== undefined;
}

// Expands to full height, matches the frame colour to the page, and turns off
// vertical swipe-to-close while this screen's own list can scroll vertically.
export function useTelegramViewport(bgColorVar: string) {
  useEffect(() => {
    const webApp = getWebApp();
    if (!webApp) return;
    webApp.ready();
    webApp.expand();
    const bg = getComputedStyle(document.documentElement).getPropertyValue(bgColorVar).trim();
    if (bg) {
      webApp.setHeaderColor(bg);
      webApp.setBackgroundColor(bg);
    }
    if (webApp.isVersionAtLeast('7.7')) {
      webApp.disableVerticalSwipes?.();
    }
    return () => {
      if (webApp.isVersionAtLeast('7.7')) {
        webApp.enableVerticalSwipes?.();
      }
    };
  }, [bgColorVar]);
}

export function useBackButton(onBack: () => void) {
  useEffect(() => {
    const webApp = getWebApp();
    if (!webApp) return;
    webApp.BackButton.show();
    webApp.BackButton.onClick(onBack);
    return () => {
      webApp.BackButton.offClick(onBack);
      webApp.BackButton.hide();
    };
  }, [onBack]);
}

export function useMainButton(options: {
  text: string;
  onClick: () => void;
  disabled: boolean;
  loading: boolean;
}) {
  const { text, onClick, disabled, loading } = options;

  useEffect(() => {
    const webApp = getWebApp();
    if (!webApp) return;
    webApp.MainButton.show();
    return () => webApp.MainButton.hide();
  }, []);

  useEffect(() => {
    const webApp = getWebApp();
    if (!webApp) return;
    webApp.MainButton.setText(text);
  }, [text]);

  useEffect(() => {
    const webApp = getWebApp();
    if (!webApp) return;
    webApp.MainButton.onClick(onClick);
    return () => webApp.MainButton.offClick(onClick);
  }, [onClick]);

  useEffect(() => {
    const webApp = getWebApp();
    if (!webApp) return;
    if (disabled) webApp.MainButton.disable();
    else webApp.MainButton.enable();
  }, [disabled]);

  useEffect(() => {
    const webApp = getWebApp();
    if (!webApp) return;
    if (loading) webApp.MainButton.showProgress(true);
    else webApp.MainButton.hideProgress();
  }, [loading]);
}

// Keeps a swipe-down from silently discarding an in-progress address form.
export function useClosingConfirmation(isDirty: boolean) {
  useEffect(() => {
    const webApp = getWebApp();
    if (!webApp) return;
    if (isDirty) webApp.enableClosingConfirmation();
    else webApp.disableClosingConfirmation();
    return () => webApp.disableClosingConfirmation();
  }, [isDirty]);
}

export function useThemeParamsAsCssVars() {
  useEffect(() => {
    const webApp = getWebApp();
    if (!webApp) return;
    const apply = () => {
      const root = document.documentElement;
      Object.entries(webApp.themeParams).forEach(([key, value]) => {
        if (value) root.style.setProperty(`--tg-theme-${key.replace(/_/g, '-')}`, value);
      });
    };
    apply();
    webApp.onEvent('themeChanged', apply);
    return () => webApp.offEvent('themeChanged', apply);
  }, []);
}

export function useHapticFeedback() {
  return getWebApp()?.HapticFeedback;
}

export function telegramAlert(message: string) {
  const webApp = getWebApp();
  if (webApp) webApp.showAlert(message);
  else window.alert(message);
}
