```tsx
// CheckoutScreen.tsx
import React, { useMemo, useState } from 'react';
import {
  isTelegramWebApp,
  telegramAlert,
  useBackButton,
  useClosingConfirmation,
  useHapticFeedback,
  useMainButton,
  useTelegramViewport,
  useThemeParamsAsCssVars,
} from './useTelegram';
import { CartItem, DeliveryAddress, EMPTY_ADDRESS } from './types';
import './CheckoutScreen.css';

interface CheckoutScreenProps {
  items: CartItem[];
  currency?: string;
  deliveryFee?: number;
  onBack: () => void;
  onPay: (address: DeliveryAddress, items: CartItem[]) => Promise<void>;
}

type FormErrors = Partial<Record<keyof DeliveryAddress, string>>;

function formatMoney(value: number, currency: string) {
  return new Intl.NumberFormat('en-US', { style: 'currency', currency }).format(value);
}

function validate(address: DeliveryAddress): FormErrors {
  const errors: FormErrors = {};
  if (!address.fullName.trim()) errors.fullName = 'Enter your full name';
  if (!/^\+?[0-9\s()-]{7,}$/.test(address.phone.trim())) errors.phone = 'Enter a valid phone number';
  if (!address.city.trim()) errors.city = 'Enter a city';
  if (!address.street.trim()) errors.street = 'Enter a street and house number';
  return errors;
}

export function CheckoutScreen({
  items,
  currency = 'USD',
  deliveryFee = 4.99,
  onBack,
  onPay,
}: CheckoutScreenProps) {
  const [address, setAddress] = useState<DeliveryAddress>(EMPTY_ADDRESS);
  const [touched, setTouched] = useState<Partial<Record<keyof DeliveryAddress, boolean>>>({});
  const [submitting, setSubmitting] = useState(false);
  const haptics = useHapticFeedback();
  const runningInTelegram = isTelegramWebApp();

  const subtotal = useMemo(
    () => items.reduce((sum, item) => sum + item.unitPrice * item.quantity, 0),
    [items]
  );
  const total = subtotal + deliveryFee;
  const errors = useMemo(() => validate(address), [address]);
  const isValid = Object.keys(errors).length === 0;
  const isDirty = Object.values(address).some((value) => value.trim() !== '');

  useTelegramViewport('--tg-theme-bg-color');
  useThemeParamsAsCssVars();
  useBackButton(onBack);
  useClosingConfirmation(isDirty && !submitting);

  function updateField<K extends keyof DeliveryAddress>(key: K, value: string) {
    setAddress((prev) => ({ ...prev, [key]: value }));
  }

  function markTouched(key: keyof DeliveryAddress) {
    setTouched((prev) => ({ ...prev, [key]: true }));
  }

  async function handlePay() {
    if (!isValid || submitting) {
      setTouched({
        fullName: true,
        phone: true,
        city: true,
        street: true,
        apartment: true,
        postalCode: true,
        comment: true,
      });
      return;
    }
    setSubmitting(true);
    try {
      await onPay(address, items);
      haptics?.notificationOccurred('success');
    } catch (error) {
      haptics?.notificationOccurred('error');
      telegramAlert(error instanceof Error ? error.message : 'Payment failed. Please try again.');
    } finally {
      setSubmitting(false);
    }
  }

  useMainButton({
    text: `Pay ${formatMoney(total, currency)}`,
    onClick: handlePay,
    disabled: !isValid || submitting || items.length === 0,
    loading: submitting,
  });

  function fieldError(key: keyof DeliveryAddress) {
    return touched[key] ? errors[key] : undefined;
  }

  return (
    <div className="checkout" style={{ paddingBottom: runningInTelegram ? '24px' : '96px' }}>
      <header className="checkout__header">
        <h1 className="checkout__title">Checkout</h1>
        <button type="button" className="checkout__edit-cart" onClick={onBack}>
          Edit cart
        </button>
      </header>

      <section className="checkout__section" aria-label="Order items">
        <ul className="cart-list">
          {items.map((item) => (
            <li key={item.id} className="cart-item">
              <div className="cart-item__thumb" aria-hidden="true">
                {item.imageUrl ? (
                  <img src={item.imageUrl} alt="" className="cart-item__img" />
                ) : (
                  <span className="cart-item__thumb-fallback">{item.title.charAt(0)}</span>
                )}
              </div>
              <div className="cart-item__details">
                <p className="cart-item__title">{item.title}</p>
                {item.description && <p className="cart-item__description">{item.description}</p>}
                <p className="cart-item__qty">Qty {item.quantity}</p>
              </div>
              <p className="cart-item__price">{formatMoney(item.unitPrice * item.quantity, currency)}</p>
            </li>
          ))}
        </ul>

        <div className="order-summary">
          <div className="order-summary__row">
            <span>Subtotal</span>
            <span>{formatMoney(subtotal, currency)}</span>
          </div>
          <div className="order-summary__row">
            <span>Delivery</span>
            <span>{formatMoney(deliveryFee, currency)}</span>
          </div>
          <div className="order-summary__row order-summary__row--total">
            <span>Total</span>
            <span>{formatMoney(total, currency)}</span>
          </div>
        </div>
      </section>

      <section className="checkout__section" aria-label="Delivery address">
        <h2 className="checkout__section-title">Delivery address</h2>
        <form className="address-form" noValidate>
          <div className="form-field">
            <label className="form-field__label" htmlFor="fullName">
              Full name
            </label>
            <input
              id="fullName"
              className="form-field__input"
              type="text"
              autoComplete="name"
              value={address.fullName}
              onChange={(e) => updateField('fullName', e.target.value)}
              onBlur={() => markTouched('fullName')}
            />
            {fieldError('fullName') && <p className="form-field__error">{fieldError('fullName')}</p>}
          </div>

          <div className="form-field">
            <label className="form-field__label" htmlFor="phone">
              Phone number
            </label>
            <input
              id="phone"
              className="form-field__input"
              type="tel"
              autoComplete="tel"
              value={address.phone}
              onChange={(e) => updateField('phone', e.target.value)}
              onBlur={() => markTouched('phone')}
            />
            {fieldError('phone') && <p className="form-field__error">{fieldError('phone')}</p>}
          </div>

          <div className="form-field">
            <label className="form-field__label" htmlFor="city">
              City
            </label>
            <input
              id="city"
              className="form-field__input"
              type="text"
              autoComplete="address-level2"
              value={address.city}
              onChange={(e) => updateField('city', e.target.value)}
              onBlur={() => markTouched('city')}
            />
            {fieldError('city') && <p className="form-field__error">{fieldError('city')}</p>}
          </div>

          <div className="form-field">
            <label className="form-field__label" htmlFor="street">
              Street and house number
            </label>
            <input
              id="street"
              className="form-field__input"
              type="text"
              autoComplete="address-line1"
              value={address.street}
              onChange={(e) => updateField('street', e.target.value)}
              onBlur={() => markTouched('street')}
            />
            {fieldError('street') && <p className="form-field__error">{fieldError('street')}</p>}
          </div>

          <div className="form-row">
            <div className="form-field">
              <label className="form-field__label" htmlFor="apartment">
                Apartment / unit
              </label>
              <input
                id="apartment"
                className="form-field__input"
                type="text"
                autoComplete="address-line2"
                value={address.apartment}
                onChange={(e) => updateField('apartment', e.target.value)}
              />
            </div>

            <div className="form-field">
              <label className="form-field__label" htmlFor="postalCode">
                Postal code
              </label>
              <input
                id="postalCode"
                className="form-field__input"
                type="text"
                autoComplete="postal-code"
                value={address.postalCode}
                onChange={(e) => updateField('postalCode', e.target.value)}
              />
            </div>
          </div>

          <div className="form-field">
            <label className="form-field__label" htmlFor="comment">
              Delivery notes (optional)
            </label>
            <textarea
              id="comment"
              className="form-field__input form-field__textarea"
              rows={3}
              value={address.comment}
              onChange={(e) => updateField('comment', e.target.value)}
            />
          </div>
        </form>
      </section>

      {/* Fallback for local development outside Telegram, where there is no
          host MainButton to collide with. */}
      {!runningInTelegram && (
        <div className="fallback-bar">
          <button
            type="button"
            className="fallback-bar__back"
            onClick={onBack}
          >
            Back
          </button>
          <button
            type="button"
            className="fallback-bar__pay"
            disabled={!isValid || submitting || items.length === 0}
            onClick={handlePay}
          >
            {submitting ? 'Processing…' : `Pay ${formatMoney(total, currency)}`}
          </button>
        </div>
      )}
    </div>
  );
}
